// Parse incoming artwork data for color analysis
const body = $input.first().json.body;

// Extract artwork information
const artworkId = body.artworkId || body.id || `artwork_${Date.now()}`;
const artworkTitle = body.title || 'Untitled Artwork';
const collection = body.collection || 'Unknown Collection';
const imageUrl = body.imageUrl || body.image_url || '';
const artist = body.artist || 'Unknown Artist';
const tags = body.tags || [];
const existingAnalysis = body.existingAnalysis || null;

// Validate required fields
if (!imageUrl || imageUrl.trim().length === 0) {
  throw new Error('Image URL is required for color analysis');
}

// Download the image to make it accessible to the MCP server
const imageFileName = `${artworkId}_${Date.now()}.jpg`;
const imagePath = `/tmp/${imageFileName}`;

// Prepare workflow data
return {
  artwork: {
    id: artworkId,
    title: artworkTitle,
    collection: collection,
    artist: artist,
    imageUrl: imageUrl,
    tags: tags,
    imagePath: imagePath,
    imageFileName: imageFileName
  },
  analysisRequest: {
    timestamp: new Date().toISOString(),
    requestId: `analysis_${Date.now()}`,
    analysisType: body.analysisType || 'comprehensive',
    skipExisting: body.skipExisting || false,
    existingAnalysis: existingAnalysis
  },
  processingSteps: [
    'download_image',
    'mcp_color_analysis',
    'process_results',
    'store_in_database',
    'generate_embeddings'
  ]
};

// Process MCP agent response and enhance with additional data
const mcpResponse = $input.first().json;
const artworkData = $('parse-artwork-data').first().json;

// Extract palette information from MCP response
const palette = mcpResponse.palette || [];
const harmony = mcpResponse.harmony || 'unknown';
const effects = mcpResponse.effects || [];

// Convert RGB tuples to hex and calculate percentages
const dominantColors = palette.map((rgb, index) => {
  const [r, g, b] = rgb;
  const hex = '#' + [r, g, b].map(x => x.toString(16).padStart(2, '0')).join('');

  // Assign decreasing percentages to colors based on prominence
  const percentage = Math.round((100 - (index * 15)) / palette.length);

  return {
    hex: hex,
    name: getColorName(rgb),
    percentage: percentage,
    rgb: { r, g, b },
    category: categorizeColor(rgb)
  };
});

// Process psychological effects
const psychologicalProfile = {
  primaryMood: effects[0]?.name || 'neutral',
  secondaryMood: effects[1]?.name || null,
  emotionalImpact: effects.map(e => e.description),
  psychologicalEffects: effects.map(e => `promotes ${e.name}`),
  atmosphereType: `${effects[0]?.name || 'balanced'} ${harmony || 'harmonious'}`
};

// Determine room recommendations based on mood
const moodToRooms = {
  'calming': ['bedroom', 'study', 'bathroom'],
  'energizing': ['office', 'gym', 'kitchen'],
  'playful': ['playroom', 'children-room', 'creative-space'],
  'natural': ['living-room', 'dining-room', 'sunroom'],
  'dramatic': ['home-theater', 'office', 'gallery'],
  'romantic': ['bedroom', 'dining-room', 'lounge'],
  'uplifting': ['kitchen', 'hallway', 'entryway'],
  'grounded': ['study', 'library', 'den'],
  'mysterious': ['bedroom', 'meditation-room', 'study'],
  'pure': ['bathroom', 'nursery', 'minimalist-space']
};

const recommendedRooms = moodToRooms[psychologicalProfile.primaryMood] || ['any-room'];

// Prepare database-ready data
const dbData = {
  // Artwork identification
  artworkId: artworkData.artwork.id,
  artworkTitle: artworkData.artwork.title,
  collection: artworkData.artwork.collection,
  artist: artworkData.artwork.artist,
  imageUrl: artworkData.artwork.imageUrl,

  // Color analysis results
  dominantColors: dominantColors,
  colorTemperature: {
    overall: categorizeTemperature(dominantColors),
    warmPercentage: calculateWarmPercentage(dominantColors),
    coolPercentage: calculateCoolPercentage(dominantColors),
    balance: 'analyzing based on palette'
  },
  colorHarmony: {
    type: harmony || 'custom',
    description: `${harmony || 'unique'} color relationship`,
    harmonyScore: harmony ? 0.85 : 0.65
  },

  // Psychological profile
  primaryMood: psychologicalProfile.primaryMood,
  secondaryMood: psychologicalProfile.secondaryMood,
  emotionalImpact: psychologicalProfile.emotionalImpact,
  psychologicalEffects: psychologicalProfile.psychologicalEffects,
  atmosphereType: psychologicalProfile.atmosphereType,

  // Spatial recommendations
  recommendedRooms: recommendedRooms,
  avoidRooms: [],
  lightingRequirements: 'adaptable to various lighting conditions',
  spaceSizeRecommendation: 'suitable for medium to large spaces',
  wallPlacement: ['focal wall', 'above furniture', 'gallery wall'],

  // Style compatibility (simplified for now)
  styleCompatibility: {
    primaryStyles: determineStyles(harmony, effects),
    secondaryStyles: ['transitional', 'eclectic'],
    furnitureRecommendations: ['complementary color accents'],
    textileColors: dominantColors.slice(0, 3).map(c => c.name),
    accentColors: []
  },

  // Search keywords
  searchKeywords: [
    `${psychologicalProfile.primaryMood} artwork`,
    `${harmony || 'artistic'} color scheme`,
    artworkData.artwork.collection.toLowerCase(),
    ...effects.map(e => `${e.name} decor`)
  ],

  // Analysis metadata
  analysisTimestamp: new Date().toISOString(),
  analysisVersion: '2.0-mcp',
  confidenceScore: 0.88,
  analysisNotes: 'Analyzed via Color Psychology MCP Server'
};

// Helper functions
function getColorName(rgb) {
  const [r, g, b] = rgb;
  // Simplified color naming based on RGB values
  if (r > 200 && g < 100 && b < 100) return 'Red';
  if (r > 200 && g > 150 && b < 100) return 'Orange';
  if (r > 200 && g > 200 && b < 100) return 'Yellow';
  if (r < 100 && g > 150 && b < 100) return 'Green';
  if (r < 100 && g < 100 && b > 150) return 'Blue';
  if (r > 150 && g < 100 && b > 150) return 'Purple';
  if (r > 200 && g < 150 && b > 180) return 'Pink';
  if (r > 150 && g > 100 && b < 100) return 'Brown';
  if (r < 50 && g < 50 && b < 50) return 'Black';
  if (r > 200 && g > 200 && b > 200) return 'White';
  if (r > 100 && g > 100 && b > 100) return 'Gray';
  return 'Mixed';
}

function categorizeColor(rgb) {
  const [r, g, b] = rgb;
  const warmth = (r * 2 + g) / 3;
  const coolness = (b * 2 + g) / 3;
  return warmth > coolness ? 'warm' : 'cool';
}

function categorizeTemperature(colors) {
  const warmCount = colors.filter(c => c.category === 'warm').length;
  const coolCount = colors.filter(c => c.category === 'cool').length;
  if (warmCount > coolCount * 1.5) return 'warm';
  if (coolCount > warmCount * 1.5) return 'cool';
  return 'neutral';
}

function calculateWarmPercentage(colors) {
  const warmColors = colors.filter(c => c.category === 'warm');
  return warmColors.reduce((sum, c) => sum + c.percentage, 0);
}

function calculateCoolPercentage(colors) {
  const coolColors = colors.filter(c => c.category === 'cool');
  return coolColors.reduce((sum, c) => sum + c.percentage, 0);
}

function determineStyles(harmony, effects) {
  const styles = [];
  if (harmony === 'complementary') styles.push('modern', 'contemporary');
  if (harmony === 'analogous') styles.push('traditional', 'classic');
  if (harmony === 'triadic') styles.push('eclectic', 'bohemian');
  if (effects.some(e => e.name === 'calming')) styles.push('minimalist');
  if (effects.some(e => e.name === 'dramatic')) styles.push('maximalist');
  if (styles.length === 0) styles.push('versatile');
  return styles;
}

// Prepare embedding text
const embeddingText = [
  artworkData.artwork.title,
  artworkData.artwork.collection,
  dbData.primaryMood,
  dbData.secondaryMood,
  ...dbData.dominantColors.map(c => c.name),
  ...dbData.recommendedRooms,
  ...dbData.searchKeywords,
  dbData.atmosphereType
].filter(Boolean).join(' ');

return {
  artworkData: artworkData,
  mcpAnalysis: mcpResponse,
  databaseData: dbData,
  embeddingText: embeddingText,
  processingStep: 'mcp_analysis_complete'
};

// Prepare response with MCP analysis results
const analysisData = $('process-mcp-results').first().json;
const storedArtwork = $('store-artwork-analysis').first().json;

// Calculate processing metrics
const startTime = new Date(analysisData.artworkData.analysisRequest.timestamp).getTime();
const endTime = Date.now();
const processingTime = endTime - startTime;

// Build comprehensive response
const response = {
  success: true,
  artwork: {
    id: analysisData.databaseData.artworkId,
    title: analysisData.databaseData.artworkTitle,
    collection: analysisData.databaseData.collection,
    artist: analysisData.databaseData.artist,
    imageUrl: analysisData.databaseData.imageUrl
  },
  colorAnalysis: {
    dominantColors: analysisData.databaseData.dominantColors,
    colorTemperature: analysisData.databaseData.colorTemperature,
    colorHarmony: analysisData.databaseData.colorHarmony,
    rawPalette: analysisData.mcpAnalysis.palette,
    harmonyType: analysisData.mcpAnalysis.harmony
  },
  psychologicalProfile: {
    primaryMood: analysisData.databaseData.primaryMood,
    secondaryMood: analysisData.databaseData.secondaryMood,
    emotionalImpact: analysisData.databaseData.emotionalImpact,
    psychologicalEffects: analysisData.databaseData.psychologicalEffects,
    atmosphereType: analysisData.databaseData.atmosphereType,
    mcpEffects: analysisData.mcpAnalysis.effects
  },
  recommendations: {
    recommendedRooms: analysisData.databaseData.recommendedRooms,
    avoidRooms: analysisData.databaseData.avoidRooms,
    lightingRequirements: analysisData.databaseData.lightingRequirements,
    spaceSizeRecommendation: analysisData.databaseData.spaceSizeRecommendation,
    wallPlacement: analysisData.databaseData.wallPlacement,
    styleCompatibility: analysisData.databaseData.styleCompatibility
  },
  searchMetadata: {
    keywords: analysisData.databaseData.searchKeywords,
    embeddingGenerated: true,
    vectorDimensions: 1536
  },
  analysisMetadata: {
    timestamp: analysisData.databaseData.analysisTimestamp,
    version: analysisData.databaseData.analysisVersion,
    confidenceScore: analysisData.databaseData.confidenceScore,
    processingTimeMs: processingTime,
    analysisNotes: analysisData.databaseData.analysisNotes,
    mcpServer: 'color-psychology-mcp'
  },
  databaseStatus: {
    stored: true,
    recordId: storedArtwork[0]?.id || analysisData.databaseData.artworkId,
    analysisStatus: 'completed'
  }
};

return response;
